            "프로페시아정 1mg의 주성분은 피나스테리드 1mg이에요. 한국오가논(주)이 공급하는 오리지널 제품이고, 식약처 품목번호는 200009059예요. 전문의약품이라 피부과·비뇨기과 처방이 필요해요.\n\n피나스테리드는 5α-환원효소 2형을 선택적으로 억제해요. 이 효소가 테스토스테론을 디하이드로테스토스테론(DHT)으로 바꾸는데, DHT는 모낭 안드로겐 수용체와 결합해 모낭을 위축시키고 성장기를 단축시켜요. 피나스테리드를 복용하면 혈중 DHT 농도가 떨어져 진행 중인 탈모를 늦추는 방식이에요. 같은 성분 5mg(프로스카)은 양성 전립선비대증 치료에 쓰이고, 1mg(프로페시아)은 남성형 탈모 적응증으로 따로 허가됐어요.\n\n첨가제는 유당수화물·미결정셀룰로스·전호화전분 등이고 정제 표면은 코팅 처리돼 있어요. 코팅이 있는 동안에는 임부가 표면을 만져도 흡수량이 적지만, 정제가 부서지면 분말이 노출돼 피부를 통해 흡수될 수 있어요. 그래서 절대 쪼개거나 가루로 만들지 않고 통째로 삼키는 게 원칙이에요.",
