            "헤어그로의 식약처 허가 적응증은 단 하나, 만 18~41세 성인 남성의 남성형 탈모(안드로겐 탈모증)예요. 41세 초과·여성·소아·원형탈모·산후 탈모는 허가 범위 밖이라 효과를 기대할 수 없어요. 시작 전에 본인의 탈모 유형이 안드로겐 탈모인지 피부과 진단으로 확인하는 게 우선이에요.\n\n효과 평가 시점은 \"일반적으로 3개월 이상\"이라고 허가사항이 명시했어요. 용량을 늘려도 유효성이 증가한다는 근거가 없어 1일 1mg을 그대로 유지해요. 사용 초기에는 새 모발이 자라며 휴지기 모발이 빠지는 \"쉐딩\"이 일시적으로 보일 수 있어요. 이 시기에 중단하면 평가가 어려워져요.\n\n복용을 중단하면 12개월 이내에 치료 효과가 사라진다고 허가사항이 직접 적었어요. 헤어그로가 오리지널 대비 가격이 낮아 장기 복용 부담을 줄이는 선택지가 되는 이유예요. 다만 가격이 낮다고 효과 평가 기준이 달라지지는 않아요. 3개월 이상 꾸준한 복용 후 평가, 1년 단위로 재평가하는 흐름은 같아요.",
