            "허가사항 용법은 \"피나스테리드로서 1일 1회 1mg을 경구투여하며, 식사와 관계없이 투여할 수 있다\"예요. 매일 같은 시간에 복용하면 혈중 농도가 일정하게 유지돼 효과 평가에 도움이 돼요.\n\n코팅 정제는 통째로 삼켜요. 쪼개거나 빻으면 안 돼요. 정제 코팅은 \"주성분이 외부로 노출되는 걸 방지\"하는 역할을 하고, 임부 또는 임신 가능성이 있는 여성이 부서진 조각을 만지면 피부를 통해 약물이 흡수돼 남성 태아의 외부생식기에 비정상을 초래할 수 있다고 허가사항이 명시했기 때문이에요.\n\n복용을 잊었으면 다음 정기 시간에 1정만 복용해요. 보충 복용은 부작용 위험만 키울 뿐 효과를 더 높이지 않아요. 30정 1팩이 1개월치이고, 90정 단위가 3개월치예요. 효과 평가 시점인 3개월에 맞춰 처방 단위를 정하면 약값을 좀 더 절약할 수 있어요.",
