          content: "여성·소아·임산부는 절대 복용 금지예요. 정제가 깨지면 임산부 피부 접촉을 차단해야 해요. 두타스테리드는 피부를 통해 흡수되어 남성 태아에게 영향을 줄 수 있어요.\n\n간 기능에 이상이 있는 분은 의사와 상담 후 복용하세요. CYP3A4 억제제(리토나비르, 케토코나졸 등)와 병용 시 두타스테리드 혈중 농도가 올라갈 수 있어요.\n\n반감기가 길어서 헌혈은 복용 중단 후 6개월 이후에 가능해요. 피나스테리드와 동시 복용은 하지 마세요. 50세 초과 남성에서는 탈모 치료 허가 범위를 벗어나니 의사와 상의하세요."
