          content: "아보페시아정은 양성 전립선 비대증 치료와 함께 만 18~50세 성인 남성의 남성형 탈모(안드로겐탈모증) 치료에 허가된 약이에요. 0.2mg은 탈모 전용 용량이에요. DHT를 강력하게 억제해서 모낭 위축을 막고, 모발 밀도를 회복시켜요.\n\n효과를 판단하려면 최소 3~6개월은 꾸준히 복용해야 해요. 피나스테리드에서 전환한 경우에도 추가 개선까지 시간이 걸려요. 복용을 중단하면 탈모가 다시 진행되므로 지속 복용이 필수예요.\n\n0.5mg 제품(아보다트 등)과 비교하면 부작용 위험이 다소 낮을 수 있지만, 효과도 약간 차이가 날 수 있어요. 전문의와 상의해서 본인에게 맞는 선택을 하세요."
